32	const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
33	const isStringArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
34	const isRuleArray = (v) => Array.isArray(v) && v.every((x) => isPlainObject(x) && typeof x.id === 'string' && typeof x.run === 'function');
