62	// Validate one manifest against the spec. `skillDirs` is the list of directory
63	// names under `<pack>/skills/` (the caller reads it; this module touches no
64	// disk). Returns `{ what, fix }` errors — the loader's error shape — never
65	// throws, so one bad manifest can't sink the run.
66	export function validateManifest(mod, { label, skillDirs = [] } = {}) {
67	  const errors = [];
68	  const at = label ? `${label}: ` : '';
69	  const err = (what, fix) => errors.push({ what: `${at}${what}`, fix });
70	
71	  if (!isPlainObject(mod)) {
72	    err('the pack has no object default export', 'export default { id, ruleRoutingGuidance, ... } from its pack.mjs');
73	    return errors;
74	  }
75	
76	  for (const key of REQUIRED) {
77	    if (!(key in mod)) err(`declares no "${key}"`, `add "${key}" — ${PACK_FIELDS[key].describe}`);
78	  }
79	  for (const [key, value] of Object.entries(mod)) {
80	    const field = PACK_FIELDS[key];
81	    if (!field) {
82	      err(`declares "${key}", which is not a pack manifest field`, `remove it, or add it to the spec in engine/pack_loader/pack-schema.mjs — the known fields are: ${Object.keys(PACK_FIELDS).join(', ')}`);
83	      continue;
84	    }
85	    if (!field.valid(value)) err(`"${key}" is not a valid value`, `${key} is ${field.describe}`);
86	  }
87	
88	  if (isPlainObject(mod.ruleRoutingGuidance)) {
89	    for (const side of ['belongs', 'excludes']) {
90	      const v = mod.ruleRoutingGuidance[side];
91	      if (typeof v !== 'string' || !v.trim()) {
92	        err(`ruleRoutingGuidance declares no "${side}"`, side === 'belongs'
93	          ? 'state the kind of content this pack owns, in at most 20 words'
94	          : 'state what belongs elsewhere and which pack owns it, in at most 20 words');
95	        continue;
96	      }
97	      const n = wordCount(v);
98	      if (n > MAX_ROUTING_WORDS) {
99	        err(`ruleRoutingGuidance.${side} is ${n} words, over the ${MAX_ROUTING_WORDS}-word cap`,
100	          `cut it to ${MAX_ROUTING_WORDS} words — it is one row of a table every session loads`);
101	      }
102	    }
103	  }
104	
105	  // A rule's scope is where it is declared; the manifest is the authority. A
106	  // rule module may still carry `scope` for the dispatch seam that reads it off
107	  // the rule object (engine/checks/helpers/work.mjs — which hands a work rule
108	  // its fluent surface), but then the two must AGREE: a module that says one
109	  // thing while the list it sits in says another is drift with a wrong context
110	  // waiting at the end of it.
111	  for (const [key, scope] of Object.entries(RULE_SCOPES)) {
112	    if (!isRuleArray(mod[key])) continue;
113	    for (const rule of mod[key]) {
114	      if ('scope' in rule && rule.scope !== scope) {
115	        err(`the rule "${rule.id}" declares scope "${rule.scope}" but sits in ${key}`,
116	          `move the rule to the list matching its scope, or drop its "scope" field — the manifest decides`);
117	      }
118	    }
119	  }
120	
121	  // The bundled-skills declaration and the tree must agree in BOTH directions:
122	  // an undeclared directory is a skill nothing announces, and a declared name
123	  // with no directory is a manifest that lies.
124	  if (isStringArray(mod.skills)) {
125	    for (const name of mod.skills) {
126	      if (!skillDirs.includes(name)) err(`declares a skill "${name}" with no skills/${name}/ directory`, `create skills/${name}/SKILL.md, or drop the declaration`);
127	    }
128	  }
129	  for (const dir of skillDirs) {
130	    if (!(mod.skills ?? []).includes(dir)) err(`bundles skills/${dir}/ but does not declare it`, `add "${dir}" to the pack's "skills" list`);
131	  }
132	
133	  return errors;
134	}
