40	// Concatenated assistant text emitted after entry `fromIndex`, up to the next
41	// owner turn (or the end of the session).
42	export function assistantTextAfter(entries, fromIndex) {
43	  const parts = [];
44	  for (let i = fromIndex + 1; i < entries.length; i += 1) {
45	    const entry = entries[i];
46	    if (humanText(entry) !== null) break;
47	    if (entry.type !== 'assistant') continue;
48	    const content = entry.message?.content;
49	    if (!Array.isArray(content)) continue;
50	    for (const block of content) {
51	      if (block?.type === 'text' && block.text) parts.push(block.text);
52	    }
53	  }
54	  return parts.join('\n');
55	}
